public_enums:
#[derive(Debug, ToPrimitive, FromPrimitive)]
/// Possible MOUNT errors
pub enum Fail {
    /// Not owner
    Perm = 1,
    /// No such file or directory
    NoEnt = 2,
    /// I/O error
    Io = 5,
    /// Permission denied
    Access = 13,
    /// Not a directory
    NoDir = 20,
    /// Invalid argument
    Inval = 22,
    /// Filename too long
    NameTooLong = 63,
    /// Operation not supported
    NotSupp = 10004,
    /// A failure on the server
    ServerFault = 10006,
}

public_traits:
#[trait_variant::make(Send)]
pub trait Mnt {
    /// Maps a pathname on the server to a NFS version 3 protocol file handle.
    ///
    /// # Parameters:
    /// * `args` --- the arguments for the Mount operation.
    ///
    /// This procedure also results in the server adding a new entry
    /// to its mount list recording that this client has mounted the directory.
    async fn mnt(
        &self,
        args: Args,
        client_addr: SocketAddr,
        cred: OpaqueAuth,
    ) -> Result<Success, Fail>;
}
